def _links(t):
    """vals[k], left[k], right[k] for the k-th real node in level order (-1 = no child)."""
    pos, c = [], 0
    for x in t:
        if x == -1:
            pos.append(-1)
        else:
            pos.append(c)
            c += 1
    vals = [x for x in t if x != -1]
    left, right = [-1] * c, [-1] * c
    for k in range(c):
        a = 2 * k + 1
        if a < len(t):
            left[k] = pos[a]
        if a + 1 < len(t):
            right[k] = pos[a + 1]
    return vals, left, right


def replaceWithCousinSums(tree):
    vals, left, right = _links(tree)
    n = len(vals)
    depth = [0] * n
    parent = [0] * n
    level_sum = []
    kids = [0] * n
    for k in range(n):
        d = depth[k]
        if d == len(level_sum):
            level_sum.append(0)
        level_sum[d] += vals[k]
        for c in (left[k], right[k]):
            if c != -1:
                depth[c] = d + 1
                parent[c] = k
                kids[k] += vals[c]
    new = [0] + [level_sum[depth[k]] - kids[parent[k]] for k in range(1, n)] if n else []
    out = []
    k = 0
    for x in tree:
        if x == -1:
            out.append(-1)
        else:
            out.append(new[k])
            k += 1
    return out
